{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Bumetanide, a loop diuretic sharing the sulfamoylbenzoic acid scaffold, showed absolute oral bioavailability of 0.79 in elderly subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Tolfenamic acid, an anthranilic acid with an ionizable carboxylate, showed absolute oral bioavailability of 61.6% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Hydrochlorothiazide, a sulfonamide diuretic, showed oral bioavailability of 66–75% in healthy adults, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, a structurally related sulfamoyl loop diuretic, had oral bioavailability of only 10% based on urinary excretion, arguing for low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior and azosemide suggest low absorption, multiple structurally related diuretics and anthranilic acids (bumetanide, tolfenamic acid, hydrochlorothiazide) show absolute oral bioavailability well above 20%. The closest record (furosemide acyl glucuronide) is a metabolite and does not directly measure parent F. On balance, F >=20% is better supported.",
  "evidence_gaps": [
    "No direct parent furosemide oral bioavailability record is provided; the closest record (C05) is for the acyl glucuronide metabolite.",
    "Fed-state-specific bioavailability data for the query or close analogues are lacking; most records are fasting or unspecified.",
    "Azosemide low-F data conflict with high-F data from bumetanide and other analogues, leaving uncertainty in transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

